'use strict';
const {test,expect}=require('@playwright/test');
const {DIALOGUE,SPEAKERS}=require('../support/unit11-12-flow');
test.use({reducedMotion:'reduce',actionTimeout:5000});
async function observe(page){await page.addInitScript(()=>{window.nativePlays=[];const play=HTMLMediaElement.prototype.play;HTMLMediaElement.prototype.play=function(...args){const entry={src:this.src,ended:false};window.nativePlays.push(entry);this.addEventListener('ended',()=>{entry.ended=true;},{once:true});return Reflect.apply(play,this,args);};});}
async function heard(page,control,path){const before=await page.evaluate(()=>window.nativePlays.length);await control.click();await expect.poll(()=>page.evaluate(({before,path})=>window.nativePlays.slice(before).some(x=>new URL(x.src).pathname===path&&x.ended),{before,path}),{timeout:15000}).toBe(true);}
const WORDS=['whose','blue','perhaps','white','catch','father','mother','blouse','sister','tie','brother','his','her','shirt','suit','skirt','son','daughter'];
const MODELS=["Whose is this handbag? It's Stella's. It's her handbag.","Whose is this car? It's Paul's. It's his car.","Whose is this coat? It's Sophie's. It's her coat.","Whose is this umbrella? It's Steven's. It's his umbrella.","Whose is this pen? It's my son's. It's his pen.","Whose is this dress? It's my daughter's. It's her dress.","Whose is this suit? It's my father's. It's his suit.","Whose is this skirt? It's my mother's. It's her skirt.","Whose is this blouse? It's my sister's. It's her blouse.","Whose is this tie? It's my brother's. It's his tie.","Whose is this pen? It's Sophie's. It's her pen.","Whose is this pencil? It's Hans's. It's his pencil."];
const REFERENCES=['Hans is here. That is his car.','Stella is here. That is her car.','Excuse me, Steven. Is this your umbrella?','I am an air hostess. My name is Britt.','Paul is here, too. That is his coat.'];
test('55 段录音从相应页面原生播放结束，课文三人、词卡和全部替换示范对应',async({page})=>{
 test.setTimeout(300000);await observe(page);const failed=[];page.on('response',r=>{if(r.status()>=400)failed.push(r.url());});await page.goto('/unit11-12/#learn/words');const words=page.locator('.stage-words');
 for(let i=0;i<WORDS.length;i++){if(i&&i%6===0)await words.getByRole('button',{name:'下一组词卡',exact:true}).click();await heard(page,words.getByRole('button',{name:WORDS[i],exact:true}),'/unit11-12/audio/'+(i<5?'l11-w'+String(i+1).padStart(2,'0'):i<13?'l12-w'+String(i-4).padStart(2,'0'):'review-w'+String(i-12).padStart(2,'0'))+'.mp3');}
 await page.getByRole('link',{name:'一件白衬衫',exact:true}).click();const story=page.locator('.stage-text');
 for(let i=0;i<16;i++){const before=await page.evaluate(()=>window.nativePlays.length);await story.getByRole('button',{name:i?'下一句':'开始听课文',exact:true}).click();await expect(story.locator('.dialogue-actor.speaking span')).toHaveText(SPEAKERS[i]);await expect.poll(()=>page.evaluate(({before,path})=>window.nativePlays.slice(before).some(x=>new URL(x.src).pathname===path&&x.ended),{before,path:'/unit11-12/audio/l11-d'+String(i+1).padStart(2,'0')+'.mp3'}),{timeout:15000}).toBe(true);await expect(story.locator('.btext span')).toHaveText(DIALOGUE.slice(0,i+1));}
 await story.getByRole('button',{name:'完成课文学习',exact:true}).click();await page.getByRole('link',{name:'谁的说清楚',exact:true}).click();const phrases=page.locator('.stage-phrases');
 for(const [text,file]of [['Whose shirt is that?','l11-d01'],['Whose is this shirt?','phrase-this'],['Whose is that tie?','phrase-that'],["Tim's shirt's white.",'l11-d09']])await heard(page,phrases.getByRole('button',{name:text,exact:true}),'/unit11-12/audio/'+file+'.mp3');
 await page.getByRole('link',{name:'认领有办法',exact:true}).click();const models=page.locator('.stage-models');await heard(page,models.getByRole('button',{name:"Whose is this shirt? It's Tim's. It's his shirt.",exact:true}),'/unit11-12/audio/l12-b00.mp3');
 for(let i=0;i<12;i++)await heard(page,models.getByRole('button',{name:MODELS[i],exact:true}),'/unit11-12/audio/l12-b'+String(i+1).padStart(2,'0')+(i===1?'-v2':'')+'.mp3');
 await models.getByText('换个人，怎么说',{exact:true}).click();for(let i=0;i<5;i++)await heard(page,models.getByRole('button',{name:REFERENCES[i],exact:true}),'/unit11-12/audio/written-a-'+String(i).padStart(2,'0')+'.mp3');
 await page.getByRole('link',{name:'归还小能手',exact:true}).click();await heard(page,page.locator('.stage-exam').getByRole('button',{name:'听一遍',exact:true}),'/unit11-12/audio/challenge-owner.mp3');
 expect(await page.evaluate(()=>new Set(window.nativePlays.filter(x=>x.ended&&x.src.includes('/unit11-12/audio/')).map(x=>new URL(x.src).pathname)).size)).toBe(55);expect(failed).toEqual([]);
});
test('子目录录音失败不放行，恢复后可重听重选，正确和错误音效统一',async({page})=>{
 test.setTimeout(60000);await observe(page);let fail=true;await page.route('**/unit11-12/audio/l11-w01.mp3',r=>fail?r.abort():r.continue());await page.goto('/lesson/unit11-12/#learn/listen');const room=page.locator('.stage-listen');await room.getByRole('button',{name:'whose',exact:true}).click();await room.getByRole('button',{name:'听一遍',exact:true}).click();await expect(room).toContainText('播放未完成，请重听。');await expect(room.getByRole('button',{name:'检查答案',exact:true})).toBeDisabled();fail=false;
 await heard(page,room.getByRole('button',{name:'再听一遍',exact:true}),'/lesson/unit11-12/audio/l11-w01.mp3');await room.getByRole('button',{name:'blue',exact:true}).click();await heard(page,room.getByRole('button',{name:'检查答案',exact:true}),'/lesson/assets/feedback/duolingo-incorrect.mp3');await expect(room.getByRole('progressbar')).toHaveAttribute('aria-valuenow','0');
 await room.getByRole('button',{name:'再试一次',exact:true}).click();await room.getByRole('button',{name:'whose',exact:true}).click();await heard(page,room.getByRole('button',{name:'听一遍',exact:true}),'/lesson/unit11-12/audio/l11-w01.mp3');await heard(page,room.getByRole('button',{name:'检查答案',exact:true}),'/lesson/assets/feedback/duolingo-correct.mp3');await expect(room.getByRole('progressbar')).toHaveAttribute('aria-valuenow','1');await expect(room.getByRole('button',{name:'给点线索',exact:true})).toHaveCount(0);
});
test('历史句重听和离开不能代替当前句，失败重试后固定对白区仍保留历史',async({page})=>{
 test.setTimeout(60000);await observe(page);await page.goto('/unit11-12/#learn/text');const room=page.locator('.stage-text');await heard(page,room.getByRole('button',{name:'开始听课文',exact:true}),'/unit11-12/audio/l11-d01.mp3');await room.getByRole('button',{name:'下一句',exact:true}).click();await heard(page,room.getByRole('button',{name:DIALOGUE[0],exact:true}),'/unit11-12/audio/l11-d01.mp3');await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeDisabled();await room.locator('.bubble-row').first().getByRole('button',{name:'看中文',exact:true}).click();await expect(room.locator('.bubble-row').first()).toContainText('那是谁的衬衫？');await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeDisabled();
 await heard(page,room.getByRole('button',{name:DIALOGUE[1],exact:true}),'/unit11-12/audio/l11-d02.mp3');await room.getByRole('button',{name:'下一句',exact:true}).click();await page.getByRole('link',{name:'谁的说清楚',exact:true}).click();await page.getByRole('link',{name:'一件白衬衫',exact:true}).click();await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeDisabled();
 let fail=true;await page.route('**/unit11-12/audio/l11-d03.mp3',r=>fail?r.abort():r.continue());await room.getByRole('button',{name:DIALOGUE[2],exact:true}).click();await expect(room.locator('.dialogue-status')).toHaveText('录音还没听完，点句子再试一次。');await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeDisabled();fail=false;await heard(page,room.getByRole('button',{name:DIALOGUE[2],exact:true}),'/unit11-12/audio/l11-d03.mp3');await expect(room.getByRole('button',{name:'下一句',exact:true})).toBeEnabled();await expect(room.locator('.bubble-row')).toHaveCount(3);
});
